MOD = 10**9 + 7

def count_paths(matrix, x, y, memo):
    if (x, y) in memo:
        return memo[(x, y)]

    total_paths = 1  # Start with 1 for the current cell itself
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < len(matrix) and 0 <= ny < len(matrix[0]) and matrix[nx][ny] < matrix[x][y]:
            total_paths += count_paths(matrix, nx, ny, memo)
            total_paths %= MOD

    memo[(x, y)] = total_paths
    return total_paths

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    matrix = []
    index = 1
    for _ in range(N):
        row = list(map(int, data[index:index + N]))
        matrix.append(row)
        index += N

    memo = {}
    total_paths = 0
    for i in range(N):
        for j in range(N):
            total_paths += count_paths(matrix, i, j, memo)
            total_paths %= MOD

    print(total_paths)

if __name__ == "__main__":
    main()
